def transform(grid):
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    fg = next((v for v in colors if v != bg), None)
    if fg is None:
        return out
    for r, row in enumerate(grid):
        positions = [c for c, v in enumerate(row) if v == fg]
        for left, right in zip(positions, positions[1:]):
            gap = right - left - 1
            if 2 <= gap <= 4 and all(row[c] == bg for c in range(left + 1, right)):
                for c in range(left + 1, right):
                    out[r][c] = 4
    return out
